import 'package:flutter/services.dart';

/// Launcher icons the user can choose from (D50, D60). [name] is shared with
/// android/.../AppIcon.kt; [preview] is generated by
/// tool/generate_app_icons.py.
enum AppIconChoice {
  // Shown in this order, like the Style setting (D59). Neon stays the
  // default (see [parse] and the manifest).
  flat('flat', 'Flat'),
  neon('neon', 'Neon'),
  grayscale('grayscale', 'Grayscale');

  const AppIconChoice(this.name, this.label);

  final String name;
  final String label;

  String get preview => 'assets/app_icons/$name.png';

  static AppIconChoice parse(Object? value) =>
      values.where((c) => c.name == value).firstOrNull ?? neon;
}

/// Reads and switches the launcher icon. Android only: Android itself keeps
/// the choice (which launcher entry is enabled), so nothing is stored in the
/// database or in backups.
class AppIconService {
  const AppIconService();

  static const channel = MethodChannel('time_tracker/app_icon');

  Future<AppIconChoice> current() async =>
      AppIconChoice.parse(await channel.invokeMethod<String>('current'));

  Future<void> set(AppIconChoice icon) =>
      channel.invokeMethod<void>('set', icon.name);
}
